```cpp
#include <vector>
#include <cmath>
#include <algorithm>
#include <numeric>

// Assuming boxes_xyxy is a vector of vectors of floats or integers
// and _area_range is a pair of floats (min, max)

std::vector<size_t> _select_boxes_by_area(const std::vector<std::vector<float>>& boxes_xyxy, 
                                          const std::pair<float, float>& area_range) {
    if (area_range.first >= area_range.second) {
        throw std::invalid_argument("Area range must be [min, max] with min < max");
    }

    std::vector<size_t> selected_indices;

    for (size_t i = 0; i < boxes_xyxy.size(); ++i) {
        const auto& box = boxes_xyxy[i];
        if (box.size() < 4) {
            continue; // Skip invalid boxes
        }

        float width = box[2] - box[0];
        float height = box[3] - box[1];
        float area = width * height;

        if (area >= area_range.first && area <= area_range.second) {
            selected_indices.push_back(i);
        }
    }

    return selected_indices;
}
```

### Notes:
- This assumes `boxes_xyxy` is a 2D vector of floats (or integers), where each inner vector represents a box with coordinates `[x1, y1, x2, y2]`.
- The function returns a vector of indices of boxes that meet the area condition.
- The `_area_range` is a `std::pair<float, float>` representing the inclusive range of areas to filter.
- You can replace `float` with `int` if you're working with integer coordinates.

